const contactForm = document.getElementById('contact-form');
const contactStatus = document.getElementById('contact-status');
contactForm.addEventListener('submit', (event) => {
  event.preventDefault();
  if (!contactForm.reportValidity()) return;
  contactStatus.textContent = 'The required fields passed the local checks. Nothing was sent or saved.';
});
contactForm.addEventListener('input', () => {
  contactStatus.textContent = '';
});
document.getElementById('contact-submit').disabled = false;

const packingDialog = document.getElementById('packing-dialog');
const packingOpen = document.getElementById('packing-open');
const packingClose = document.getElementById('packing-close');
if (typeof packingDialog.showModal === 'function') {
  packingOpen.addEventListener('click', () => {
    if (!packingDialog.open) packingDialog.showModal();
  });
  packingClose.addEventListener('click', () => {
    packingDialog.close();
  });
  packingOpen.disabled = false;
} else {
  document.getElementById('packing-support').textContent = 'This browser cannot open the modal. Bring water, closed-toe shoes, and weather-appropriate clothing.';
}

if ('showPopover' in HTMLElement.prototype && 'popoverTargetElement' in HTMLButtonElement.prototype) {
  document.getElementById('watering-popover').hidden = false;
  document.getElementById('watering-fallback').hidden = true;
  document.getElementById('watering-trigger').hidden = false;
}

const validationForm = document.getElementById('validation-form');
const validationEmail = document.getElementById('validation-email');
const validationError = document.getElementById('validation-email-error');
const validationStatus = document.getElementById('validation-status');
function clearEmailError() {
  validationEmail.removeAttribute('aria-invalid');
  validationEmail.setAttribute('aria-describedby', 'validation-email-hint');
  validationError.hidden = true;
}
validationForm.addEventListener('submit', (event) => {
  event.preventDefault();
  validationStatus.textContent = '';
  if (!validationEmail.validity.valid) {
    validationError.textContent = validationEmail.validity.valueMissing
      ? 'Enter your email address.'
      : 'Enter an email address such as alex@example.org.';
    validationError.hidden = false;
    validationEmail.setAttribute('aria-invalid', 'true');
    validationEmail.setAttribute('aria-describedby', 'validation-email-hint validation-email-error');
    validationEmail.focus();
    validationStatus.textContent = 'Email check failed. Review the email address field.';
    return;
  }
  clearEmailError();
  validationStatus.textContent = 'The email format passed the local check. Nothing was sent or saved.';
});
validationEmail.addEventListener('input', () => {
  validationStatus.textContent = '';
  if (validationEmail.validity.valid) clearEmailError();
});
document.getElementById('validation-submit').disabled = false;

const notesAdd = document.getElementById('notes-add');
const notesForm = document.getElementById('notes-form');
const notesText = document.getElementById('notes-text');
const notesList = document.getElementById('notes-list');
const notesStatus = document.getElementById('notes-status');
notesAdd.addEventListener('click', () => {
  notesForm.hidden = false;
  notesStatus.textContent = '';
  notesText.focus();
});
document.getElementById('notes-cancel').addEventListener('click', () => {
  notesForm.reset();
  notesForm.hidden = true;
  notesStatus.textContent = 'Note discarded.';
  notesAdd.focus();
});
notesForm.addEventListener('submit', (event) => {
  event.preventDefault();
  if (!notesForm.reportValidity()) return;
  const note = document.createElement('li');
  note.textContent = notesText.value;
  notesList.append(note);
  notesList.hidden = false;
  document.getElementById('notes-empty').hidden = true;
  notesForm.reset();
  notesForm.hidden = true;
  notesStatus.textContent = 'Note added to this page. It will disappear on reload.';
  notesAdd.focus();
});
notesAdd.disabled = false;
